import{_ as s,c as t,o as n,j as a,a as r}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"漢上易傳卷十一","description":"漢上易傳 - 漢上易傳卷十一","frontmatter":{"title":"漢上易傳卷十一","description":"漢上易傳 - 漢上易傳卷十一"},"headers":[],"relativePath":"classics/hanshang/012.md","filePath":"classics/hanshang/012.md"}'),l={name:"classics/hanshang/012.md"};function c(o,e,i,d,p,h){return n(),t("div",null,[...e[0]||(e[0]=[a("h1",{id:"漢上易傳卷十一",tabindex:"-1"},[r("漢上易傳卷十一 "),a("a",{class:"header-anchor",href:"#漢上易傳卷十一","aria-label":"Permalink to “漢上易傳卷十一”"},"​")],-1),a("p",null,"雜卦專以剛柔升降反覆取義，又揉雜眾卦以暢無窮之用。而歸藏、連山，三代之易皆在其中。百世之後，有聖人作，不外是也。康節曰：乾坤三變，坎離不動，故太玄準之以玄衝、玄錯，",-1),a("p",null,"乾剛坤柔，比樂師憂，臨、觀之義，或與或求。屯見而不失其居，蒙雜而著。震，起也；艮，止也。損、益，盛衰之始也。大畜，時也，無妄災也。萃聚而升不來也。謙輕而豫怠也。噬嗑食也。賁無色也。兌見而巽伏也。隨無故也。蠱則飭也。剝爛也。復反也。晉晝也。明夷誅也。井通而困相遇也。鹹速也。恆久也。渙離也。節止也。解緩也。蹇難也。睽外也。家人內也。否泰反其類也。大壯則止。遁則退也。大有，眾也。同人，親也。革，去故也。鼎，取新也。小過，過也。中孚，信也。豐，多故也。親寡。旅也。離上而坎下也。小畜，寡也。履，不處也。需，不進也。訟，不親也。大過，顛也。遘，遇也。柔遇剛也。漸，女歸待男行也。頤，養正也。既濟，定也。歸妹，女之終也。未濟，男之窮也。夬，決也。剛決柔也。君子道長，小人道憂也。",-1),a("p",null,"乾坤，易之門。凡剛皆乾也，凡柔皆坤也。剛柔相雜，乃成諸卦，故曰乾剛坤柔。比得位而眾比之，故樂。師犯難而眾從之，故憂。憂樂以天下也。臨之九二在下，四陰與之，故能以大臨小。觀之九五在上，四陰求之，故能以上觀下。或與或求，乃成臨觀之義。屯自震變四之五雖見於屯也，而不失其所居，所以大亨。歟蒙自坎變，五之上陰陽相雜，雖雜也，而九自著見，陰豈能蒙之所以蒙亨。歟。陽起於坤而出震，則靜者動。陽止於艮而入坤，則動者靜。故起莫如震，止莫如艮也。損以九三為上，由泰而損始衰者也。益以九四益初，由否而益始盛者也。故損益盛衰之始也。大畜以四五之柔而畜三陽，時也。無妄九五六二中正，而三四上爻為無妄之疾災也。關子明曰：無妄而災者，災也。有妄而災者，其所宜也，非災之者也。萃，二陽萃於上，升，二陽升於下。升者，往也。升往則不來矣。不來者，必聚於上也。氣之方升，誰能遏之？故曰萃聚而升不來也。謙自上降三，豫自初升四，謙故降也。輕豫故怠而止，故曰謙輕而豫怠也。噬嗑，除間者也。四為頤，中有物，故曰噬嗑食也。賁自泰來，本無色也。剛柔交錯，然後有文，故曰賁無色也。陰隨陽升，說而見乎外，故曰兌見也。陽隨陰降，巽而伏乎內，故曰巽伏也。施說之道，小者亦伸，處巽之時，大者亦屈，無非天也。隨，隨時也，以是為正，故曰隨無故也。蠱，壞也。二往之五，飭蠱之道，故曰蠱則飭也。剝，爛也。五陰潰於內也。復，反也。剝，上反於下也。晉之明進而至於晝，明夷之明降而至於誅。夷，誅也。其明熄矣，非誅之象乎。泰初之五，往來不窮，故曰井通。否上之二陽遇陰而見揜，故曰困相遇也。或往而通，或來而困，唯其時也。以剛下柔，其感必速，故曰鹹感也。剛上柔下，可以持久，故曰恆久也。渙三陽渙離，故曰渙離也。節三陽止而不去，故曰節止也。陽離則三陰散，陽止則三陰來。陽者，陰之表也。蹇二往五涉難也，故曰蹇難也。解五來二復吉也，故曰解，緩也。來者為緩，則往者當夙，故曰有攸往，夙吉。關子明曰：明乎外者物自聧，故曰聧外也。明乎內者家自齊，故曰家人內也。君子泰則小人否，小人泰則君子否，故曰否泰反其類也。四陽並進，六五以和易待之，可以止而仕也，故曰大壯則止。四陽偕往，二陰在內而執其柄，可以退而去也，故曰遁則退也。同人六二得中得位而同乎人，同乎人則人亦親之，故曰同人親也。大有六五柔得尊位而有其眾，有其眾則眾亦歸之，故曰大有眾也。水火相革，革已廢也，故曰革去故也。以木巽火，火方興也，故曰鼎取新也。功成者退，方來者進，一去一取，天之道也。小過二陽在內，動而止，小者過也，故曰小過過也。中孚二陰在內，伏而說，小者信也，故曰中孚信也。豐泰二之四進退不得其所，多故也。多故則難處，故曰豐多故也。旅，否三之五，失位無應，以其旅於外也。旅外者，不如在內之為安，故曰親寡旅也。禮，多故也，故四五相錯，然後有慶。親寡旅也，故五動二應而後有譽。離火炎上也，故陽爻多兇。坎水趣下也，故陰爻多兇。坎離相濟者也。小畜五陽而畜一陰，所畜者寡，故曰小畜寡也。履一柔而履二剛，不處為善，故曰履不處也。需險在前，三陽需時而不進。關子明曰：履而不處者，其周公乎。需而不進者，其仲尼乎。險在下而陽上行相過者也。故曰訟不親也。自大過顛也，而下簡冊錯亂，當曰頤養正也。大過顛也。遘，遇也。遘當作姤，柔遇剛也。夬，決也，剛決柔也。君子道長，小人道憂也。漸，女歸，待男行也。歸妹，女之終也。既濟，定也。未濟，男之窮也。頤一陽在上而養四，陰，正也，故其卦以下養上為顛。大過一陰在上，四陽無所託，顛也。故其卦初陰承陽，無失位之兇。陰宜在下也。姤以一柔而遇五剛，故曰姤遇也，柔遇剛也。夬以五剛而決一柔，故曰夬決也，剛決柔也。姤，小人道長，君子道憂也，故繫於金柅。夬，君子道長，小人道憂也，故無號之兇。女以外為歸，乾男下而迎三，然後坤女行而歸，故曰漸歸，待男行也。歸妹以三易四，男行而女從，夫婦之正也。上六無應，守正而終不改之義也。故曰歸妹，女之終也。既濟虞翻曰：六爻得位，定也。故曰既濟，定也。未濟伊川曰：三陽失位，故曰未濟，男之窮也。周易雜卦傳第十一。",-1)])])}const f=s(l,[["render",c]]);export{_ as __pageData,f as default};
